INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'A dyeing recipe calls for 2% owf (on weight of fabric) of a reactive dye. For a batch of 500 kg fabric, how many kg of dye are needed?', '["10 kg","2 kg","25 kg","1 kg"]'::jsonb, '10 kg', 'Dye needed = %owf × fabric weight = 0.02 × 500 kg = 10 kg.', 1, '{"dye-recipe-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'A dyeing recipe calls for 1.5% owf of a reactive dye. For a batch of 800 kg fabric, how many kg of dye are needed?', '["12 kg","1.5 kg","53.3 kg","8 kg"]'::jsonb, '12 kg', 'Dye needed = %owf × fabric weight = 0.015 × 800 kg = 12 kg.', 1, '{"dye-recipe-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'A dyeing machine uses a liquor ratio of 1:10 for a 300 kg fabric batch. How many liters of dye liquor are needed?', '["3,000 liters","300 liters","30 liters","10 liters"]'::jsonb, '3,000 liters', 'Liquor volume = liquor ratio × fabric weight = 10 × 300 kg = 3,000 liters (assuming 1 kg fabric corresponds to 1 liter liquor unit in the ratio).', 1, '{"liquor-ratio-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'A dyeing machine uses a liquor ratio of 1:8 for a 500 kg fabric batch. How many liters of dye liquor are needed?', '["4,000 liters","500 liters","62.5 liters","8 liters"]'::jsonb, '4,000 liters', 'Liquor volume = liquor ratio × fabric weight = 8 × 500 kg = 4,000 liters.', 1, '{"liquor-ratio-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A recipe requires 60 g/L of salt at a liquor ratio of 1:10 for a 200 kg fabric batch. How many kg of salt are needed in total?', '["120 kg","60 kg","12 kg","200 kg"]'::jsonb, '120 kg', 'Total liquor volume = 10 × 200 kg = 2,000 liters. Total salt = 60 g/L × 2,000 L = 120,000 g = 120 kg.', 2, '{"salt-dosing-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A recipe requires 40 g/L of salt at a liquor ratio of 1:12 for a 250 kg fabric batch. How many kg of salt are needed in total?', '["120 kg","40 kg","10 kg","250 kg"]'::jsonb, '120 kg', 'Total liquor volume = 12 × 250 kg = 3,000 liters. Total salt = 40 g/L × 3,000 L = 120,000 g = 120 kg.', 2, '{"salt-dosing-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A dye costs $15 per kg. If a recipe uses 2% owf of this dye for a 1,000 kg fabric batch, what is the approximate total dye cost?', '["$300","$15","$30","$1,500"]'::jsonb, '$300', 'Dye needed = 0.02 × 1,000 kg = 20 kg. Total cost = 20 kg × $15/kg = $300.', 2, '{"dye-cost-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A dye costs $20 per kg. If a recipe uses 1.5% owf of this dye for a 600 kg fabric batch, what is the approximate total dye cost?', '["$180","$20","$40","$900"]'::jsonb, '$180', 'Dye needed = 0.015 × 600 kg = 9 kg. Total cost = 9 kg × $20/kg = $180.', 2, '{"dye-cost-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A fabric is padded and shows a wet pickup of 70% (its weight increases by 70% of its dry weight after padding). For 100 kg of dry fabric, what is the total wet weight after padding?', '["170 kg","70 kg","130 kg","700 kg"]'::jsonb, '170 kg', 'Wet weight = dry weight + (wet pickup% × dry weight) = 100 + (0.70 × 100) = 100 + 70 = 170 kg.', 2, '{"wet-pickup-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A fabric is padded and shows a wet pickup of 80%. For 250 kg of dry fabric, what is the total wet weight after padding?', '["450 kg","200 kg","330 kg","80 kg"]'::jsonb, '450 kg', 'Wet weight = dry weight + (wet pickup% × dry weight) = 250 + (0.80 × 250) = 250 + 200 = 450 kg.', 2, '{"wet-pickup-calc"}'::text[]);
